css:
.notifications-container {
  width: 320px;
  height: auto;
  font-size: 0.875rem;
  line-height: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.flex {
  display: flex;
}

.flex-shrink-0 {
  flex-shrink: 0;
}

.info {
  background-color: rgb(239, 246, 255);
  border-left-width: 4px;
  border-radius: 0.375rem;
  padding: 1rem;
}

.info-svg {
  height: 1.25rem;
  width: 1.25rem;
  opacity: 70%;
  color: rgb(29, 78, 216);
}

.info-prompt-wrap {
  margin-left: 0.75rem;
  color: rgb(29, 78, 216);
}

.info-prompt-link {
  font-weight: 500;
  color: rgb(0, 29, 110);
  text-decoration: underline;
}

.info-prompt-link:hover {
  color: rgb(29, 78, 216);
}
